substitutions:
    integer relation_reuse_checks=0,relation_mem_cases=0,relation_wb_cases=0;
    integer relation_stall_cases=0,relation_load_cases=0;
    always @(posedge clk) begin
        if(rst_n && core.ex_valid) begin
            if(LOAD_USE_BUBBLE!=0) begin
                if(core.early_result!==core.operand_relation(core.forwarded_a,core.forwarded_b))
                    $fatal(1,"FAIL reused relation differs from forwarded operands");
                relation_reuse_checks=relation_reuse_checks+1;
            end
            if(core.early_source_a[2] || core.early_source_b[2]) relation_mem_cases=relation_mem_cases+1;
            if(core.early_source_a[3] || core.early_source_b[3]) relation_wb_cases=relation_wb_cases+1;
            if(!core.ex_fire) relation_stall_cases=relation_stall_cases+1;
            if(core.mem_valid && core.mem_load) relation_load_cases=relation_load_cases+1;
        end
    end
    task report_relation_reuse;
        begin
            if(LOAD_USE_BUBBLE!=0 && relation_reuse_checks==0) $fatal(1,"FAIL no live relation reuse checks");
            if(relation_load_cases==0 || relation_stall_cases==0 || relation_wb_cases==0 || relation_mem_cases==0)
                $fatal(1,"FAIL incomplete relation forwarding coverage");
            $display("PASS relation reuse=%0d mem=%0d wb=%0d stalls=%0d load=%0d bubble=%0d",relation_reuse_checks,
                relation_mem_cases,relation_wb_cases,relation_stall_cases,relation_load_cases,LOAD_USE_BUBBLE);
        end
    endtask
endmodule

