if(LOAD_USE_BUBBLE!=0)
check((core.ex_decode.is_branch && core.ex_instruction[14:13]==0) || core.ex_decode.is_load,"only BEQ/BNE or load address may bypass a MEM load");
else begin
    if(core.ex_decode.uses_rs1 && core.ex_rs1==core.mem_rd)
        check(core.forwarded_a===core.mem_value,"direct load operand A forwarding");
    if(core.ex_decode.uses_rs2 && core.ex_rs2==core.mem_rd)
        check(core.forwarded_b===core.mem_value,"direct load operand B forwarding");
    if(!core.ex_decode.is_branch && !core.ex_decode.is_load) direct_load_forward_count=direct_load_forward_count+1;
end

if(LOAD_USE_BUBBLE!=0)
check(LOAD_USE_BUBBLE!=0 && load_wait_count>0 && wb_load_forward_count>0 && load_forward_count>0 && zero_offset_forward_count>0 && positive_load_forward_count>0 && negative_load_forward_count>0,"zero positive and negative load-address bypass coverage");
else check(load_wait_count==0 && load_forward_count>0 && direct_load_forward_count>0,"direct load forwarding without bubble restriction");
